#!/usr/bin/env python3
"""Generate qml/theme/Theme.qml from design/tokens.json.

The design canvas (design/screens) and the app share one token file, so a
palette or spacing change is made once. Run after editing tokens.json:

    python3 pulse/tools/gen-theme.py
"""
import json
import pathlib
import sys

root = pathlib.Path(__file__).resolve().parent.parent
tokens = json.loads((root / "design" / "tokens.json").read_text())

lines = [
    "// Generated by tools/gen-theme.py from design/tokens.json. Do not edit by hand.",
    "pragma Singleton",
    "import QtQuick",
    "",
    "QtObject {",
]

for name, spec in tokens["color"].items():
    lines.append(f'    readonly property color {name}: "{spec["value"]}"')
lines.append("")

grad = tokens["gradient"]["accent"]
lines.append(f'    readonly property var accentGradient: {json.dumps(grad)}')
lines.append("")

font = tokens["font"]
lines.append(f'    readonly property string fontFamily: "{font["family"]}"')
for key in ("display", "title", "section", "body", "meta"):
    lines.append(f'    readonly property int {key}Size: {font[key]["size"]}')
    lines.append(f'    readonly property int {key}Weight: {font[key]["weight"]}')
lines.append(f'    readonly property int displaySizeCompact: {font["display"]["mobile"]}')
lines.append(f'    readonly property int wordmarkSize: {font["wordmark"]["size"]}')
lines.append(f'    readonly property real wordmarkSpacing: {font["wordmark"]["letterSpacingEm"]}')
lines.append("")

names = ["xs", "s", "m", "l", "xl", "xxl", "xxxl"]
for n, v in zip(names, tokens["space"]):
    lines.append(f"    readonly property int space{n.upper()}: {v}")
lines.append("")

for k, v in tokens["radius"].items():
    lines.append(f"    readonly property int radius{k[0].upper()}{k[1:]}: {v}")
lines.append("")

for k, v in tokens["size"].items():
    lines.append(f"    readonly property int {k}: {v}")
lines.append("")

for k, v in tokens["motion"].items():
    lines.append(f"    readonly property int motion{k[0].upper()}{k[1:]}: {v}")

lines.append("}")
out = root / "qml" / "theme" / "Theme.qml"
out.write_text("\n".join(lines) + "\n")
print(f"wrote {out.relative_to(root)}", file=sys.stderr)
